function bandText(v,threshold,upper,lower){return v==null||String(v).trim()===''?'لم يُدخل العدد بعد':Number(v)>=threshold?upper:lower}
function participationFields(){return `<div id="participation-section"><div class="eyebrow">♡ التطوع والمشاركة والمبادرة</div><h2>مشاركاتي وبصمتي في المدرسة</h2><p>أدخلي الأعداد الفعلية خلال فترة التقييم ${esc(settings.start)} إلى ${esc(settings.end)}. اكتبي صفرًا عند عدم وجود مشاركة. يظهر وصف موجز للمشاركة تلقائيًا بحسب العدد المدخل.</p>${field('allGoalsAchieved','هل حققتِ جميع أهدافك، وتوفرت الشواهد عليها بنسبة ١٠٠٪؟','select',{required:true,options:['نعم','لا']})}<div class="participation-evidence" id="goal-evidence" ${draft.allGoalsAchieved==='نعم'?'':'hidden'}>${field('goalsEvidence','رابط شواهد تحقيق الأهداف','url',{required:draft.allGoalsAchieved==='نعم',hint:'إلزامي عند الإجابة بنعم.'})}</div>${participationItems.map(([key,icon,label,threshold,upper,lower])=>`<section class="participation-card"><h3><span class="participation-icon">${icon}</span>${label}</h3>${field(key,key==='volunteerHours'?'أدخلي عدد ساعات التطوع':'أدخلي العدد الفعلي','number',{required:true})}<div class="pill" id="band-${key}">${bandText(draft[key],threshold,upper,lower)}</div><div class="participation-evidence" id="evidence-${key}" ${Number(draft[key]||0)>0?'':'hidden'}>${field(key+'Evidence','رابط الشاهد الداعم (إلزامي عند وجود مشاركة)','url',{required:Number(draft[key]||0)>0,hint:'الشاهد إلزامي عند تسجيل مشاركة أو ساعات تطوع.'})}</div></section>`).join('')}${field('contributionsImpact','اذكري مساهماتك في حل المشكلات والأثر الذي أحدثته','textarea')}${field('electronicNomination','هل بادرتِ عند طلب الترشح لتنفيذ عمل أو مهمة إلكترونية؟','select',{required:true,options:['نعم، بادرت بالترشح','لم أبادر بالترشح','لم يُطلب الترشح لمهمة إلكترونية']})}<div class="participation-evidence" id="nomination-evidence" ${draft.electronicNomination==='نعم، بادرت بالترشح'?'':'hidden'}>${field('nominationDetails','اذكري المهمة الإلكترونية التي ترشحتِ لها ونتيجتها','textarea',{required:draft.electronicNomination==='نعم، بادرت بالترشح'})}${field('nominationEvidence','رابط شاهد المبادرة للترشح','url',{required:draft.electronicNomination==='نعم، بادرت بالترشح'})}</div></div>`}
function updateParticipationFields(){for(const [key,,label,threshold,upper,lower] of participationItems){const band=$('#band-'+key);if(band)band.textContent=bandText(draft[key],threshold,upper,lower);toggleEvidence('evidence-'+key,Number(draft[key]||0)>0)}toggleEvidence('goal-evidence',draft.allGoalsAchieved==='نعم');toggleEvidence('nomination-evidence',draft.electronicNomination==='نعم، بادرت بالترشح');const absence=$('#band-absence');if(absence)absence.textContent=draft.absExc==null||draft.absExc===''?'لم يُدخل العدد بعد':Number(draft.absExc)<=5?'خمسة أيام فأقل':'أكثر من خمسة أيام';const permission=$('#band-permission');if(permission)permission.textContent=draft.permissions==null||draft.permissions===''?'لم يُدخل العدد بعد':Number(draft.permissions)<=5?'خمس مرات فأقل':'أكثر من خمس مرات'}
function toggleEvidence(id,show){const el=$('#'+id);if(!el)return;el.hidden=!show;el.querySelectorAll('input,textarea').forEach(input=>input.required=show)}
function participationReport(r){return `<h2>المشاركات والتطوع والمبادرات</h2><div class="course"><h3>تحقيق جميع الأهداف وتوفر شواهدها بنسبة ١٠٠٪</h3><p>${esc(r.allGoalsAchieved||'لم يُسجل')}</p>${evidenceAnchor(r.goalsEvidence)}</div><div class="formgrid">${participationItems.map(([key,icon,label,threshold,upper,lower,oldKey])=>{const v=r[key]??r[oldKey];return `<div class="course"><h3>${icon} ${label}</h3><p>${v==null||v===''?'لم يُسجل':num(Number(v))+(key==='volunteerHours'?' ساعة':'')}</p><span class="pill">${bandText(v,threshold,upper,lower)}</span><div>${evidenceAnchor(r[key+'Evidence'])}</div></div>`}).join('')}</div><h3>المساهمات وأثرها</h3><p style="white-space:pre-wrap">${esc(r.contributionsImpact||'لم يُذكر')}</p><h3>المبادرة عند طلب الترشح لمهمة إلكترونية</h3><p>${esc(r.electronicNomination||'لم يُسجل')}</p><p>${esc(r.nominationDetails||'')}</p>${evidenceAnchor(r.nominationEvidence)}`}
function evidenceAnchor(url){return safeUrl(url)?`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">عرض الشاهد ↗</a>`:''}
const steps=['البيانات الأساسية','الجدارات والمبادرة','الاحتياجات التدريبية والتقنية','المشاركات والتطوع والأثر','التطوير والنمو المهني','المراجعة والإرسال'];
function selectedNeeds(d){return Object.entries(d.needs||{}).filter(([_,n])=>n.selected).map(([id,n])=>({...n,id,label:trainingNeeds[Number(id)]||n.label||'احتياج إضافي'}))}
function needsHtml(){return `<h2>الاحتياجات التدريبية والتقنية لتنمية الإبداع</h2><p>تختلف الاحتياجات حسب المسمى الوظيفي والمهام ومستوى الإتقان. اختاري البنود المناسبة لعملك فقط، ثم حدّدي مستوى إتقانك الحالي وأولوية الاحتياج. البنود المتخصصة اختيارية ولا يُفترض احتياج الجميع إليها.</p><div class="notice">قائمة شاملة تضم ${num(trainingNeeds.length)} بندًا في ${num(needGroups.length)} مجالًا، تشمل التدريب والتجهيزات والدعم التقني. اختاري ما يدعم نموك وإبداعك المهني.</div>${needGroups.map(([g,items],gi)=>`<details class="needs-group" ${gi===0?'open':''}><summary><b>${g}</b><span class="pill">${num(items.length)} بنود</span></summary>${items.map(label=>{const id=String(trainingNeeds.indexOf(label)),n=draft.needs?.[id]||{};return `<div class="need-item"><label class="choice"><input type="checkbox" data-need="${id}" data-key="selected" ${n.selected?'checked':''}>${label}</label><div class="need-details" ${n.selected?'':'hidden'}><div class="formgrid"><div class="field"><label for="nl${id}">${gi===12?'مستوى التوفر الحالي':'مستوى الإتقان الحالي'}</label><select id="nl${id}" data-need="${id}" data-key="level"><option value="">اختاري…</option>${(gi===12?['غير متوفر','متوفر جزئيًا','متوفر ويحتاج تحسينًا','متوفر وكافٍ']:['مبتدئ / لم أستخدمه','أساسي','متوسط','متقدم','متقن وأستطيع تدريب الآخرين']).map(v=>`<option ${n.level===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="np${id}">أولوية الاحتياج</label><select id="np${id}" data-need="${id}" data-key="priority"><option value="">اختاري…</option>${['عالية','متوسطة','منخفضة'].map(v=>`<option ${n.priority===v?'selected':''}>${v}</option>`).join('')}</select></div></div></div></div>`}).join('')}</details>`).join('')}<h3 class="section-gap">تخصيص الاحتياج</h3>${field('otherTraining','احتياجات أخرى غير موجودة في القائمة','textarea')}${field('needsContext','ارتباط الاحتياجات بمهامك الوظيفية والتحديات التي تواجهك','textarea')}${field('preferredTraining','أسلوب التطوير المفضّل','select',{options:['تدريب حضوري عملي','تدريب عن بُعد','تدريب فردي / إرشاد مهني','تعلّم ذاتي','مجتمع مهني وتبادل خبرات','مزيج من الأساليب']})}`}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function num(n){return new Intl.NumberFormat('ar-SA',{maximumFractionDigits:1}).format(n)}
function field(key,label,type='text',opts={}){const value=draft[key]??'';return `<div class="field"><label for="${key}">${label}${opts.required?' <span aria-label="مطلوب">*</span>':''}</label>${type==='textarea'?`<textarea id="${key}" name="${key}" ${opts.required?'required':''} maxlength="4000">${esc(value)}</textarea>`:type==='select'?`<select id="${key}" name="${key}" ${opts.required?'required':''}><option value="">اختاري…</option>${opts.options.map(x=>`<option ${value===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:`<input id="${key}" name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="'+(key==='volunteerHours'?'0.25':'1')+'"':''} ${type==='url'?'pattern="https://.*" placeholder="https://" dir="ltr"':''} ${opts.required?'required':''} maxlength="500">`}${opts.hint?`<small>${opts.hint}</small>`:''}</div>`}
function checks(key,arr){return arr.map(x=>`<label class="choice"><input type="checkbox" name="${key}" value="${esc(x)}" ${Array.isArray(draft[key])&&draft[key].includes(x)?'checked':''}>${esc(x)}</label>`).join('')}
function title(k,h,p,action=''){return `<div class="titlebar"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div>${action}</div>`}
function stat(label,value,foot,icon){return `<div class="card"><div class="stat-head">${label}<span class="stat-icon">${icon}</span></div><strong class="stat-number">${num(value)}</strong><div class="stat-foot">${foot}</div></div>`}
function average(fn){return records.length?records.reduce((a,r)=>a+fn(r),0)/records.length:0}
function dashboard(){const courses=records.flatMap(r=>r.courses||[]),needs=records.flatMap(selectedNeeds),evidence=records.reduce((sum,r)=>sum+competencies.filter((_,i)=>safeUrl(r['cl'+i])).length,0);return `<section class="hero hero-renewed"><div class="hero-copy"><div class="eyebrow"><span class="hero-line"></span> رحلتي… أثرٌ ونمو</div><h1>بصمتي المهنية</h1><h2>التأمل الذاتي في الجدارات والإنجازات المهنية</h2><p>لكل جهدٍ حكاية، ولكل إنجازٍ بصمة.<br>تأمّلي ممارساتك، وثّقي أثر عطائك، وامنحي نموّك المهني مساحة يستحقها.</p><div class="hero-actions"><button class="btn hero-cta" data-go="survey">ابدئي رحلة التأمل <span>←</span></button><button class="btn hero-secondary" data-go="growth">استكشفي نموك المهني</button></div><div class="hero-points"><span>✧ تأمّل واعٍ</span><span>▤ شواهد موثّقة</span><span>↗ نمو مستمر</span></div></div><div class="hero-art"><img src="professional-growth.webp" alt="دفتر إنجاز مهني وقلم وبصمة ونبتة ترمز للنمو، بتصميم أخضر وذهبي" fetchpriority="high" width="768" height="512"><div class="art-caption"><span>✦</span><div>بصمة تُروى… وأثرٌ يبقى<small>كل خطوة تعلّم تصنع فرقًا</small></div></div></div></section><div class="overview-heading"><div><div class="eyebrow">مساحتي المهنية</div><h2>نظرة على رحلة العطاء</h2></div><button class="textlink" data-go="records">استعراض السجل ←</button></div><div class="stats">${stat('التأملات المكتملة',records.length,'تقييمات أُرسلت من هذا المتصفح','▤')}${stat('ساعات التطوع',records.reduce((sum,r)=>sum+Number(r.volunteerHours??r.m17??0),0),'ساعات عطاء ومشاركة مجتمعية','♡')}${stat('الاحتياجات المحددة',needs.length,'اختيارات تدريبية وتقنية','✧')}${stat('ساعات التطوير',courses.reduce((a,c)=>a+Number(c.hours||0),0),'ساعة تعلم ونمو مهني','◷')}</div><div class="columns"><section class="card"><div class="card-title"><h2>توثيق الجدارات الوظيفية</h2><small>عدد التأملات ذات الشواهد</small></div>${competencies.map((c,i)=>{const count=records.filter(r=>safeUrl(r['cl'+i])).length;return `<div class="bar-row"><span>${c[0]}</span><div class="track"><div class="fill ${i===3?'gold':''}" style="width:${records.length?count/records.length*100:0}%"></div></div><b>${num(count)}</b></div>`}).join('')}<p>الشواهد تحكي الممارسة وتدعم التأمل في أثرها.</p></section><section class="card"><div class="card-title"><h2>أولويات التطوير</h2><small>الاحتياجات المختارة</small></div>${['عالية','متوسطة','منخفضة'].map(pr=>{const n=needs.filter(x=>x.priority===pr).length;return `<div class="bar-row"><span>أولوية ${pr}</span><div class="track"><div class="fill" style="width:${needs.length?n/needs.length*100:0}%"></div></div><b>${num(n)}</b></div>`}).join('')}<p>خطوة واعية لبناء خطة نمو تنطلق من احتياجك.</p></section></div><section class="card section-gap"><div class="card-title"><h2>آخر التأملات المهنية</h2><button class="textlink" data-go="records">عرض السجل ←</button></div>${recordTable(records.slice(-4).reverse())}</section>`}

function recordTable(rows){return !rows.length?'<div class="empty">لا توجد تقييمات بعد. ابدئي أول تقييم لتظهر هنا مؤشرات واقعية.<br><button class="textlink" data-go="survey">ابدئي التقييم الذاتي ←</button></div>':`<div class="tablewrap"><table><thead><tr><th>الموظفة</th><th>المسمى الوظيفي</th><th>شواهد الجدارات</th><th>الاحتياجات</th><th>التقرير</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b><br><small>${esc(r.date?.slice(0,10))}</small></td><td>${esc(r.job)}</td><td><span class="pill">${num(competencies.filter((_,i)=>safeUrl(r['cl'+i])).length)} شواهد</span></td><td>${num(selectedNeeds(r).length)}</td><td><button class="textlink" data-report="${r.id}">عرض</button></td></tr>`).join('')}</tbody></table></div>`}

function contentStep(){if(step===0)return `<h2>قبل أن تبدئي</h2><p>عزيزتي المساعدة الإدارية، يهدف النموذج إلى قراءة جداراتك وتوثيق إنجازاتك والتعرف على احتياجاتك التطويرية. اختاري أداءك الفعلي، وجهّزي الشواهد لمراجعتها في اللقاء المهني. يستغرق التقييم نحو ١٥ دقيقة.</p><div class="notice">فترة التقييم: ${esc(settings.start)} إلى ${esc(settings.end)}. يحتوي هذا النموذج على بيانات مهنية؛ احتفظي بنسخة التصدير في مكان خاص.</div><div class="formgrid">${field('name','الاسم الكامل','text',{required:true})}${field('job','المسمى الوظيفي','text',{required:true})}${field('department','الإدارة أو القسم','select',{required:true,options:['الإدارة المدرسية','الشؤون الإدارية','الشؤون التعليمية','الشؤون الطلابية','السكرتارية','أخرى']})}${field('experience','عدد سنوات الخبرة في الوظيفة الحالية','select',{required:true,options:['أقل من سنتين','٢–٥ سنوات','٦–١٠ سنوات','أكثر من ١٠ سنوات']})}${field('qualification','المؤهل العلمي','select',{options:['ثانوي','دبلوم','بكالوريوس','ماجستير','دكتوراه','أخرى']})}</div><h2 class="section-gap">الغياب والاستئذان</h2><p>أدخلي الأعداد الفعلية خلال فترة التقييم، واكتبي صفرًا عند عدم وجود غياب أو استئذان.</p><div class="formgrid">${field('absExc','عدد أيام الغياب بعذر','number',{required:true,hint:'<span id="band-absence">'+(draft.absExc==null||draft.absExc===''?'لم يُدخل العدد بعد':Number(draft.absExc)<=5?'خمسة أيام فأقل':'أكثر من خمسة أيام')+'</span>'})}${field('absNo','عدد أيام الغياب بدون عذر','number',{required:true})}${field('permissions','عدد مرات الاستئذان','number',{required:true,hint:'<span id="band-permission">'+(draft.permissions==null||draft.permissions===''?'لم يُدخل العدد بعد':Number(draft.permissions)<=5?'خمس مرات فأقل':'أكثر من خمس مرات')+'</span>'})}</div>`;
if(step===1)return `<h2>الجدارات الوظيفية</h2><p>لكل جدارة اختاري الوصف الأقرب لممارستك، وأضيفي مثالًا مهنيًا ورابط الشاهد الداعم. جميع شواهد الجدارات إلزامية.</p>${competencies.map((c,i)=>`<div class="competency"><h3>${c[0]}</h3><p>${c[1]}</p><div class="rating">${levels.map((l,j)=>`<label class="choice" title="${definitions[j]}"><input type="radio" name="c${i}" value="${j+1}" ${Number(draft['c'+i])===j+1?'checked':''} required>${l}<small class="stat-foot" style="display:block">${definitions[j]}</small></label>`).join('')}</div>${field('ce'+i,c[2],'textarea',{required:true})}${field('cl'+i,'رابط شاهد الجدارة','url',{required:true,hint:'أرفقي رابطًا صالحًا للشاهد مع إتاحة الاطلاع للمسؤول المباشر.'})}</div>`).join('')}<h2 class="section-gap">المبادرة والتقنية</h2>${field('initiative','الأعمال التي بادرتِ بتولّيها دون تكليف وأثرها على سير العمل','textarea')}${field('techInitiative','المبادرة في المهام التقنية','select',{options:['أبادر إلى التنفيذ فور الطلب وأقترح تحسينات','أنفذ العمل كاملًا عند الطلب وبدقة','أنفذه بمساعدة أو توجيه','لم يُطلب مني عمل تقني هذا العام']})}${field('techWork','الأعمال التقنية: العمل والأداة المستخدمة والنتيجة','textarea')}<h3>المهارات التقنية التي تتقنينها</h3><div class="formgrid">${checks('tech',tech)}</div>${field('techOther','مهارات تقنية أخرى')}`;
if(step===2)return needsHtml();
if(step===3)return `${participationFields()}<h2 class="section-gap">القوة والتطوير والأثر</h2><p>تأملات مهنية لإبراز نقاط القوة وفرص التطوير والأثر.</p>${field('strengths','أبرز نقاط القوة المهنية مع مثال لكل نقطة','textarea')}${field('improvements','ماذا ترغبين في تطويره، وماذا فعلتِ لتطويره هذا العام؟','textarea')}${[1,2,3].map(i=>field('achievement'+i,'الإنجاز '+i+' وأثره على سير العمل','textarea')).join('')}${field('challenge','أكبر تحدٍّ واجهتِه وكيف تعاملتِ معه','textarea')}${field('notes','ملاحظات إضافية للإدارة','textarea')}`;
if(step===4)return `<h2>التطوير والنمو المهني</h2><p>سجل مهني لتوثيق التعلّم وتطبيقه وأثره. أرفقي رابط شهادة أو شاهد لكل نشاط تضيفينه.</p><div id="courses">${(draft.courses||[]).map((c,i)=>courseHtml(c,i)).join('')}</div><button type="button" class="btn" id="add-course">＋ إضافة نشاط نمو مهني</button><h2 class="section-gap">خطة التطوير القادمة</h2><h3>الجدارات التي ترغبين في تطويرها</h3>${checks('developCompetencies',competencies.map(c=>c[0]))}<div class="notice">حدّدي الاحتياجات التدريبية والتقنية ومستوى إتقانها وأولوياتها في الخطوة الثالثة.</div>${field('growthGoal','الهدف التطويري القادم','textarea')}${field('growthActions','خطوات التنفيذ والأدوات المطلوبة','textarea')}<div class="formgrid">${field('growthDeadline','الموعد المستهدف','date')}${field('growthMeasure','مؤشر قياس نجاح التطوير')}</div>${field('support','الدعم المتوقع من الإدارة أو المسؤول المباشر','textarea')}${field('suggestions','اقتراحات تحسين بيئة العمل وإجراءاته','textarea')}`;
return `<h2>المراجعة والإرسال</h2><p>راجعي البيانات قبل حفظ التقييم النهائي. النتيجة قراءة ذاتية وفق الملف وتحتاج مراجعة الشواهد من المسؤول المباشر.</p><div class="stats">${stat('الجدارات المكتملة',competencies.filter((_,i)=>draft['c'+i]&&draft['ce'+i]&&safeUrl(draft['cl'+i])).length,'جدارات مع شواهد داعمة','◈')}${stat('الاحتياجات المحددة',selectedNeeds(draft).length,'احتياجات تدريبية وتقنية','✓')}${stat('أنشطة النمو المهني',(draft.courses||[]).length,'أنشطة موثّقة' ,'✧')}</div><div class="notice">${esc(draft.name||'لم يُدخل الاسم')} · ${esc(draft.job||'لم يُدخل المسمى')}</div><h3>المرفقات والشواهد</h3>${field('attachments','روابط شهادات التدريب والمبادرات والفعاليات واللجان وسجل التطوع','textarea',{required:true,hint:'رابط HTTPS لكل سطر. تأكدي من صلاحية الوصول للمسؤول المباشر.'})}<label class="choice"><input name="declaration" type="checkbox" ${draft.declaration?'checked':''} required>أقر بأن المعلومات الواردة صحيحة، ولديّ الشواهد الداعمة لها، وأن بياناتي ستُستخدم في المراجعة المهنية ودعم التطوير.</label><p>نقدّر جهدك وعطاءك، ونرى في هذا النموذج فرصة لإبراز ما تقدمينه وتحديد ما نقدمه لك من دعم. شكرًا لوقتك وصدقك.</p>`}
function courseHtml(c,i){const cf=(k,label,type='text')=>`<div class="field"><label>${label}</label>${type==='textarea'?`<textarea data-course="${i}" data-key="${k}" maxlength="4000">${esc(c[k]||'')}</textarea>`:`<input data-course="${i}" data-key="${k}" type="${type}" value="${esc(c[k]??'')}" ${type==='number'?'min="0" max="10000" step="0.5"':''} ${type==='url'?'pattern="https://.*" dir="ltr"':''} ${k==='title'||k==='link'?'required':''}>`}</div>`;return `<div class="course"><div class="card-title"><h3>نشاط النمو المهني ${i+1}</h3><button type="button" class="textlink" data-remove-course="${i}">حذف النشاط</button></div><div class="formgrid">${cf('title','عنوان النشاط *')}<div class="field"><label>نوع النشاط</label><select data-course="${i}" data-key="type">${['دورة تدريبية','ورشة عمل','مجتمع مهني','تعلّم ذاتي','تبادل خبرات وزيارات','لقاء مهني'].map(t=>`<option ${c.type===t?'selected':''}>${t}</option>`).join('')}</select></div>${cf('provider','الجهة المقدمة')}${cf('date','تاريخ التنفيذ','date')}${cf('hours','عدد الساعات','number')}${cf('link','رابط شهادة الحضور أو الشاهد *','url')}</div>${cf('skills','المهارات والمعارف المكتسبة','textarea')}${cf('application','كيف طُبّق التعلّم في العمل؟','textarea')}${cf('impact','الأثر ونتيجة القياس قبل التطبيق وبعده','textarea')}</div>`}
function survey(){return title('استبيان التأمل الذاتي','رحلتي في التأمل المهني','تأملي ممارساتك، ووثّقي أثرها، وحدّدي خطوتك القادمة.')+`<div class="progress"><div style="width:${(step+1)/steps.length*100}%"></div></div><div class="steps">${steps.map((s,i)=>`<button type="button" data-step="${i}" class="${step===i?'current':''}">${i+1}. ${s}</button>`).join('')}</div><form id="survey-form"><section class="card">${contentStep()}<div class="form-actions"><button type="button" class="btn" id="prev" ${step===0?'disabled':''}>السابق</button><div><button type="button" class="btn" id="save-draft">حفظ المسودة</button> <button class="btn primary" type="submit">${step===5?'إرسال وحفظ التقييم':'حفظ ومتابعة ←'}</button></div></div></section></form>`}
function capture(e){if(draft.__submission)delete draft.__submission;const t=e.target;if(t.dataset.need!==undefined){draft.needs=draft.needs||{};const id=t.dataset.need;draft.needs[id]=draft.needs[id]||{};draft.needs[id][t.dataset.key]=t.type==='checkbox'?t.checked:t.value;if(t.type==='checkbox')t.closest('.need-item').querySelector('.need-details').hidden=!t.checked}else if(t.dataset.course!==undefined){const c=draft.courses[Number(t.dataset.course)];c[t.dataset.key]=t.value}else if(t.name){if(t.type==='checkbox'){if(t.name==='declaration')draft.declaration=t.checked;else draft[t.name]=[...document.querySelectorAll(`input[name="${t.name}"]:checked`)].map(x=>x.value)}else if(t.type!=='radio'||t.checked)draft[t.name]=t.value}save('draft',draft);updateParticipationFields();}

function validateAll(){for(const k of ['name','job','department','experience'])if(!String(draft[k]||'').trim())return [0,'أكملي البيانات الأساسية.'];for(const k of ['absExc','absNo','permissions'])if(String(draft[k]??'').trim()===''||!Number.isSafeInteger(Number(draft[k]))||Number(draft[k])<0)return[0,'أدخلي أعدادًا صحيحة غير سالبة للغياب والاستئذان، أو صفرًا عند عدم وجودها.'];for(let i=0;i<4;i++)if(!draft['c'+i]||!String(draft['ce'+i]||'').trim())return[1,'اختاري مستوى كل جدارة وأضيفي شاهدها الوصفي.'];for(let i=0;i<4;i++)if(!safeUrl(draft['cl'+i]))return[1,'رابط شاهد صالح لكل جدارة إلزامي ويجب أن يبدأ بـ HTTPS.'];for(const n of selectedNeeds(draft))if(!n.level||!n.priority)return[2,'حدّدي مستوى الإتقان أو التوفر وأولوية كل احتياج مختار.'];for(const [key] of participationItems){const v=draft[key];if(v==null||String(v).trim()===''||!Number.isFinite(Number(v))||Number(v)<0||(key==='volunteerHours'?!Number.isSafeInteger(Number(v)*4):!Number.isSafeInteger(Number(v))))return[3,'أكملي أعداد المشاركات والتطوع بقيم صحيحة غير سالبة، أو صفرًا عند عدم وجودها.'];if(Number(v)>0&&!safeUrl(draft[key+'Evidence']))return[3,'أرفقي رابط شاهد صالحًا لكل مشاركة أو ساعات تطوع مسجّلة.'];}if(!['نعم','لا'].includes(draft.allGoalsAchieved))return[3,'أجيبي عن تحقيق جميع الأهداف وتوفر شواهدها.'];if(draft.allGoalsAchieved==='نعم'&&!safeUrl(draft.goalsEvidence))return[3,'أرفقي رابط شواهد تحقيق الأهداف.'];if(!['نعم، بادرت بالترشح','لم أبادر بالترشح','لم يُطلب الترشح لمهمة إلكترونية'].includes(draft.electronicNomination))return[3,'أجيبي عن المبادرة عند طلب الترشح لمهمة إلكترونية.'];if(draft.electronicNomination==='نعم، بادرت بالترشح'&&(!String(draft.nominationDetails||'').trim()||!safeUrl(draft.nominationEvidence)))return[3,'اذكري المهمة الإلكترونية وأرفقي رابط شاهد المبادرة للترشح.'];for(const c of draft.courses||[])if(!String(c.title||'').trim())return[4,'أضيفي عنوان كل نشاط نمو مهني أو احذفي النشاط الفارغ.'];for(const [k,v]of Object.entries(draft))if(/^cl\d+$/.test(k)&&v&&!safeUrl(v))return[1,'روابط الشواهد يجب أن تبدأ بـ HTTPS.'];for(const c of draft.courses||[])if(!safeUrl(c.link))return[4,'رابط الشاهد إلزامي لكل نشاط نمو مهني ويجب أن يبدأ بـ HTTPS.'];if(!String(draft.attachments||'').trim())return[5,'إضافة روابط المرفقات والشواهد إلزامية.'];if(draft.attachments&&draft.attachments.split('\n').some(l=>l.trim()&&!safeUrl(l.trim())))return[5,'ضعي رابط HTTPS صالحًا في كل سطر من المرفقات.'];return null}
function exportData(){const data={version:1,exportedAt:new Date().toISOString(),settings,records,draft};download(JSON.stringify(data,null,2),'numou-backup.json','application/json');}
function download(data,name,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function growth(){const courses=records.flatMap(r=>(r.courses||[]).map(c=>({...c,employee:r.name})));return title('التعلّم المستمر','النمو المهني','من حضور النشاط إلى تطبيق المعرفة وقياس الأثر.',`<button class="btn primary" data-growth-start>＋ توثيق نشاط</button>`)+`<div class="stats">${stat('أنشطة التطوير',courses.length,'إجمالي الأنشطة الموثقة','✧')}${stat('ساعات التعلّم',courses.reduce((a,c)=>a+Number(c.hours||0),0),'ساعة تدريب ونمو مهني','◷')}${stat('أنشطة تم تطبيقها',courses.filter(c=>c.application?.trim()).length,'أنشطة لها تطبيق موثق','✓')}${stat('أنشطة لها قياس أثر',courses.filter(c=>c.impact?.trim()).length,'أنشطة لها وصف للأثر','◈')}</div><section class="card"><h2>سجل أنشطة النمو المهني</h2>${courses.length?courses.map(c=>`<div class="course"><span class="pill">${esc(c.type)}</span><h3 class="section-gap">${esc(c.title)}</h3><p>${esc(c.employee)} · ${esc(c.provider)} · ${esc(c.date)} · ${num(Number(c.hours||0))} ساعة</p><b>التطبيق في العمل</b><p>${esc(c.application||'لم يُوثّق بعد')}</p><b>الأثر وقياسه</b><p>${esc(c.impact||'لم يُوثّق بعد')}</p>${safeUrl(c.link)?`<a href="${esc(safeUrl(c.link))}" target="_blank" rel="noopener noreferrer">عرض الشاهد ↗</a>`:''}</div>`).join(''):'<div class="empty">أضيفي أنشطة النمو المهني ضمن التقييم، ثم أرسليه لتظهر هنا.</div>'}</section><section class="card section-gap"><h2>الاحتياجات التدريبية</h2>${needGroups.map(([g,items])=>{const count=records.reduce((sum,r)=>sum+selectedNeeds(r).filter(n=>items.includes(n.label)).length,0);const total=records.flatMap(selectedNeeds).length;return `<div class="bar-row"><span>${g}</span><div class="track"><div class="fill" style="width:${total?count/total*100:0}%"></div></div><b>${num(count)}</b></div>`}).join('')}</section>`}
function report(id){const r=records.find(r=>r.id===id);if(!r)return;const value=(l,v)=>`<h3>${esc(l)}</h3><p style="white-space:pre-wrap">${esc(v||'لم يُذكر')}</p>`,link=l=>safeUrl(l)?`<a href="${esc(safeUrl(l))}" target="_blank" rel="noopener noreferrer">عرض الشاهد ↗</a>`:'';$('#content').innerHTML=title('تقرير تقييم ذاتي',esc(r.name),'الجدارات والاحتياجات التدريبية والتقنية والنمو المهني.',`<button class="btn" id="print">طباعة / PDF</button>`)+`<section class="card">${value('المسمى والقسم',r.job+' · '+r.department)}${value('فترة التقييم',(r.period?.start||settings.start)+' إلى '+(r.period?.end||settings.end))}<div class="stats">${stat('شواهد الجدارات',competencies.filter((_,i)=>safeUrl(r['cl'+i])).length,'روابط شواهد داعمة','◈')}${stat('ساعات التطوير',(r.courses||[]).reduce((a,c)=>a+Number(c.hours||0),0),'ساعة تعلم موثّقة','✓')}${stat('الاحتياجات',selectedNeeds(r).length,'تدريبية وتقنية','▤')}${stat('النمو المهني',(r.courses||[]).length,'أنشطة تطوير','✧')}</div><h2>الغياب والاستئذان</h2><div class="formgrid">${value('عدد أيام الغياب بعذر',r.absExc==null||r.absExc===''?'لم يُسجل':num(Number(r.absExc)))}${value('عدد أيام الغياب بدون عذر',r.absNo==null||r.absNo===''?'لم يُسجل':num(Number(r.absNo)))}${value('عدد مرات الاستئذان',(r.permissions??r.m9)==null||(r.permissions??r.m9)===''?'لم يُسجل':num(Number(r.permissions??r.m9)))}</div><h2>الجدارات والشواهد</h2>${competencies.map((c,i)=>value(c[0]+' · '+(levels[Number(r['c'+i])-1]||'لم يحدد'),r['ce'+i])+link(r['cl'+i])).join('')}<h2>المبادرة والتقنية</h2>${value('الأعمال التي بادرَت بتولّيها',r.initiative)}${value('المبادرة التقنية',r.techInitiative)}${value('الأعمال التقنية والأدوات والنتائج',r.techWork)}${value('المهارات التقنية',[...(r.tech||[]),r.techOther||''].filter(Boolean).join('، '))}${participationReport(r)}<h2>الاحتياجات التدريبية والتقنية</h2>${selectedNeeds(r).length?`<div class="tablewrap"><table><thead><tr><th>الاحتياج</th><th>الإتقان / التوفر</th><th>الأولوية</th></tr></thead><tbody>${selectedNeeds(r).map(n=>`<tr><td>${esc(n.label)}</td><td>${esc(n.level)}</td><td>${esc(n.priority)}</td></tr>`).join('')}</tbody></table></div>`:'<p>لا توجد احتياجات مفصّلة مسجلة في هذا التقييم.</p>'}${value('احتياجات إضافية',r.otherTraining)}${value('ارتباط الاحتياجات بالمهام',r.needsContext)}${value('أسلوب التطوير المفضّل',r.preferredTraining)}<h2>القوة والتطوير والأثر</h2>${[['strengths','نقاط القوة'],['improvements','مواطن التطوير'],['achievement1','الإنجاز الأول وأثره'],['achievement2','الإنجاز الثاني وأثره'],['achievement3','الإنجاز الثالث وأثره'],['challenge','التحديات'],['notes','الملاحظات']].map(([k,l])=>value(l,r[k])).join('')}<h2>النمو المهني</h2>${(r.courses||[]).map(c=>`<div class="course">${value(c.title,c.type+' · '+(c.provider||'')+' · '+(c.date||'')+' · '+(c.hours||0)+' ساعة')}${value('المهارات المكتسبة',c.skills)}${value('التطبيق',c.application)}${value('الأثر',c.impact)}${link(c.link)}</div>`).join('')}${value('الجدارات المستهدفة',(r.developCompetencies||[]).join('، '))}${[['growthGoal','الهدف القادم'],['growthActions','خطوات التنفيذ'],['growthDeadline','الموعد المستهدف'],['growthMeasure','قياس النجاح'],['support','الدعم المطلوب'],['suggestions','مقترحات تحسين العمل']].map(([k,l])=>value(l,r[k])).join('')}<h2>المرفقات</h2>${(r.attachments||'').split('\n').filter(Boolean).map(l=>`<div>${link(l.trim())}</div>`).join('')}<div class="notice">أقرّت الموظفة بصحة البيانات وتوفر الشواهد عند الإرسال بتاريخ ${esc(r.date.slice(0,10))}. التأملات الواردة وصفية للمراجعة المهنية ودعم التطوير.</div><button class="btn" data-go="records">العودة إلى السجل</button></section>`;$('#print').onclick=()=>window.print();wire();window.scrollTo(0,0)}

function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&(b.dataset.participation!==undefined?step===3:b.dataset.view!=='survey'||step!==3)));$('#school').textContent=settings.school;window.BasmatiAdmin?.setActive(view==='admin');if(view==='admin'){window.BasmatiAdmin.mount({host:$('#content'),needLabel:id=>trainingNeeds[Number(id)]||'احتياج إضافي',openReport:r=>{showFormalReport(r,{back:'admin'});const b=document.createElement('button');b.className='btn';b.textContent='تسجيل خروج الإدارة';b.onclick=()=>window.BasmatiAdmin.logout();document.querySelector('.report-actions')?.append(b);},onLock:()=>{if(view==='admin')render();}});return;}$('#content').innerHTML=view==='dashboard'?dashboard():view==='survey'?survey():view==='growth'?growth():view==='settings'?settingsView():title('أرشيف الأداء','سجل التقييمات','تقييماتي وتقاريري المهنية على هذا الجهاز.',`<button class="btn" id="export">تصدير نسخة البيانات ↓</button>`)+`<section class="card"><div class="filters"><input id="search" aria-label="البحث" placeholder="ابحثي باسم الموظفة أو المسمى الوظيفي…"></div><div id="records-list">${recordTable(records.slice().reverse())}</div></section>`;wire();
if(view==='survey'){const form=$('#survey-form');form.addEventListener('input',capture);form.addEventListener('change',capture);form.onsubmit=async e=>{e.preventDefault();if(step<5){step++;render();window.scrollTo(0,0);return}const error=validateAll();if(error){step=error[0];render();toast(error[1]);return}if(!draft.declaration){toast('الإقرار بصحة البيانات مطلوب.');return}const record=draft.__submission||{...JSON.parse(JSON.stringify(draft)),id:crypto.randomUUID(),date:new Date().toISOString(),period:{...settings}};delete record.__submission;draft.__submission=record;save('draft',draft);const controls=[...document.querySelectorAll('button,input,select,textarea')].filter(el=>!el.disabled);controls.forEach(el=>el.disabled=true);try{const receipt=await window.BasmatiDB.submit(record);record.databaseSavedAt=receipt.saved_at;records=[...records.filter(r=>r.id!==record.id),record];draft={};save('draft',draft);step=0;view='dashboard';render();report(record.id);}catch(error){console.error('Submission failed',error.name);toast(error.message||'تعذّر إرسال التقييم. حاولي مرة أخرى.');}finally{controls.forEach(el=>el.disabled=false);}};$('#prev').onclick=()=>{if(step>0){step--;render()}};$('#save-draft').onclick=()=>{save('draft',draft)};$('#add-course')?.addEventListener('click',()=>{draft.courses=draft.courses||[];draft.courses.push({type:'دورة تدريبية'});save('draft',draft);render()});document.querySelectorAll('[data-remove-course]').forEach(b=>b.onclick=()=>{draft.courses.splice(Number(b.dataset.removeCourse),1);save('draft',draft);render()})}
$('#export')?.addEventListener('click',exportData);$('#search')?.addEventListener('input',e=>{const q=e.target.value.trim();$('#records-list').innerHTML=recordTable(records.filter(r=>(r.name+' '+r.job).includes(q)).reverse());wire()});mountLogoSettings();}

function wire(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render();window.scrollTo(0,0)});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render()});document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>report(b.dataset.report));document.querySelectorAll('[data-growth-start]').forEach(b=>b.onclick=()=>{view='survey';step=4;render()})}
function survey(){return title('استبيان التأمل الذاتي','رحلتي في التأمل المهني','تأملي ممارساتك، ووثّقي أثرها، وحدّدي خطوتك القادمة.')+`<div class="progress"><div style="width:${(step+1)/steps.length*100}%"></div></div><div class="steps">${steps.map((s,i)=>`<button type="button" data-step="${i}" class="${step===i?'current':''}">${i+1}. ${s}</button>`).join('')}</div><form id="survey-form"><section class="card">${contentStep()}<div class="form-actions"><button type="button" class="btn" id="prev" ${step===0?'disabled':''}>السابق</button><div class="final-actions"><button type="button" class="btn" id="save-draft">حفظ المسودة</button>${step===5?' <button type="button" class="btn print-ready" id="print-draft">▣ تصدير PDF تفاعلي</button>':''} <button class="btn primary" type="submit">${step===5?'إرسال التقرير وحفظ التقييم':'حفظ ومتابعة ←'}</button></div></div></section></form>`}

function present(v,unit=''){return v==null||String(v).trim()===''?'لم يُسجل':esc(String(v))+unit}
function qrSvg(url){try{if(typeof qrcode!=='function')return '';const qr=qrcode(0,'M');qr.addData(url);qr.make();return qr.createSvgTag({cellSize:2,margin:8,scalable:true})}catch(error){console.warn('QR generation skipped',error);return ''}}
function reportLink(url,label='فتح الشاهد التفاعلي'){const valid=safeUrl(url);if(!valid)return 'لا يوجد';let shown=valid;try{const parsed=new URL(valid);shown=parsed.hostname+(parsed.pathname==='/'?'':parsed.pathname)}catch{}if(shown.length>58)shown=shown.slice(0,55)+'…';const qr=qrSvg(valid);return `<div class="evidence-access">${qr?`<a class="qr-card" href="${esc(valid)}" target="_blank" rel="noopener noreferrer" aria-label="مسح رمز QR لفتح الشاهد">${qr}<small>امسحي للعرض</small></a>`:''}<a class="report-link" href="${esc(valid)}" target="_blank" rel="noopener noreferrer" title="اضغطي لفتح الملف أو الشاهد"><span>${esc(label)} ↗</span><small>${esc(shown)}</small></a></div>`}
function summaryTable(rows,heads=['البيان','التفاصيل']){return `<div class="formal-table-wrap"><table class="formal-table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>`<${i===0?'th':'td'}>${cell==null||cell===''?'لم يُذكر':cell}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function reportSection(titleText,content){return `<section class="formal-section"><h2>${esc(titleText)}</h2>${content}</section>`}
function displayNumber(value,unit=''){return value==null||value===''?'لم يُسجل':num(Number(value))+unit}

function formalReportHtml(r,isDraft=false){
  const period=r.period||settings;
  const reportDate=(r.date||new Date().toISOString()).slice(0,10);
  const needs=selectedNeeds(r);
  const attachmentLinks=(r.attachments||'').split('\n').map(x=>x.trim()).filter(Boolean);
  const competenciesRows=competencies.map((c,i)=>[
    esc(c[0]),
    esc(levels[Number(r['c'+i])-1]||'لم يُحدد'),
    `<span class="preserve-lines">${esc(r['ce'+i]||'لم يُذكر')}</span>`,
    reportLink(r['cl'+i])
  ]);
  const participationRows=participationItems.map(([key,,label,threshold,upper,lower,oldKey])=>{
    const value=r[key]??r[oldKey];
    return [esc(label),displayNumber(value,key==='volunteerHours'?' ساعة':''),esc(bandText(value,threshold,upper,lower)),reportLink(r[key+'Evidence'])];
  });
  const coursesRows=(r.courses||[]).map(c=>[
    esc(c.title||'لم يُذكر'),
    esc(c.type||'لم يُذكر'),
    esc([c.provider,c.date,c.hours!==''&&c.hours!=null?num(Number(c.hours))+' ساعة':''].filter(Boolean).join(' · ')||'لم يُذكر'),
    `<span class="preserve-lines"><b>المكتسب:</b> ${esc(c.skills||'لم يُذكر')}<br><b>التطبيق:</b> ${esc(c.application||'لم يُذكر')}<br><b>الأثر:</b> ${esc(c.impact||'لم يُذكر')}</span>`,
    reportLink(c.link)
  ]);
  const schoolName=r.period?.school||settings.school||'الابتدائية الثانية والعشرون بخميس مشيط';
  return `<article class="formal-report">
    <div class="report-letterhead">
      <div class="letterhead-side"><b>المملكة العربية السعودية</b><span>وزارة التعليم</span><span>الإدارة العامة للتعليم بمنطقة عسير</span><span>مكتب تعليم خميس مشيط</span><strong>${esc(schoolName)}</strong></div>
      ${reportLogoHtml(r)}
      <div class="letterhead-side letterhead-meta"><span>التاريخ: ${esc(reportDate)}</span><span>فترة التقييم</span><b>${esc(period.start||settings.start)} إلى ${esc(period.end||settings.end)}</b></div>
    </div>
    <div class="report-heading"><div class="report-fingerprint">ب</div><div><span>بصمتي المهنية</span><h1>تقرير التأمل الذاتي في الجدارات والإنجازات المهنية</h1><p>ملخص مهني متكامل للبيانات والشواهد والاحتياجات وخطة النمو</p></div></div>
    ${reportSection('أولًا: البيانات الأساسية',summaryTable([
      ['اسم الموظفة',esc(r.name||'لم يُذكر')],['المسمى الوظيفي',esc(r.job||'لم يُذكر')],['الإدارة أو القسم',esc(r.department||'لم يُذكر')],['سنوات الخبرة',esc(r.experience||'لم يُذكر')],['المؤهل العلمي',esc(r.qualification||'لم يُذكر')]
    ]))}
    ${reportSection('ثانيًا: ملخص الغياب والاستئذان',summaryTable([
      ['الغياب بعذر',displayNumber(r.absExc,' يوم')],['الغياب بدون عذر',displayNumber(r.absNo,' يوم')],['مرات الاستئذان',displayNumber(r.permissions??r.m9,' مرة')]
    ]))}
    ${reportSection('ثالثًا: الجدارات المهنية وشواهدها',summaryTable(competenciesRows,['الجدارة','مستوى الممارسة','ملخص التأمل والمثال المهني','الشاهد']))}
    ${reportSection('رابعًا: المبادرة والمهارات التقنية',summaryTable([
      ['الأعمال التي بادرت بتوليها',`<span class="preserve-lines">${esc(r.initiative||'لم يُذكر')}</span>`],
      ['المبادرة في المهام التقنية',esc(r.techInitiative||'لم يُذكر')],
      ['الأعمال التقنية والأدوات والنتائج',`<span class="preserve-lines">${esc(r.techWork||'لم يُذكر')}</span>`],
      ['المهارات التقنية',esc([...(r.tech||[]),r.techOther||''].filter(Boolean).join('، ')||'لم يُذكر')]
    ]))}
    ${reportSection('خامسًا: المشاركات والتطوع والأثر',
      summaryTable([
        ['تحقيق جميع الأهداف وتوفر شواهدها بنسبة ١٠٠٪',esc(r.allGoalsAchieved||'لم يُسجل'),reportLink(r.goalsEvidence)]
      ],['البيان','الإجابة','الشاهد'])+
      summaryTable(participationRows,['البند','العدد الفعلي','الملخص','الشاهد'])+
      summaryTable([
        ['المساهمات في حل مشكلات المدرسة وأثرها',`<span class="preserve-lines">${esc(r.contributionsImpact||'لم يُذكر')}</span>`],
        ['المبادرة عند طلب الترشح لمهمة إلكترونية',esc(r.electronicNomination||'لم يُسجل')],
        ['المهمة الإلكترونية ونتيجتها',`<span class="preserve-lines">${esc(r.nominationDetails||'لم يُذكر')}</span> ${reportLink(r.nominationEvidence)}`]
      ])
    )}
    ${reportSection('سادسًا: نقاط القوة والإنجازات وفرص التطوير',summaryTable([
      ['نقاط القوة المهنية',`<span class="preserve-lines">${esc(r.strengths||'لم يُذكر')}</span>`],
      ['مواطن التطوير',`<span class="preserve-lines">${esc(r.improvements||'لم يُذكر')}</span>`],
      ['الإنجاز الأول وأثره',`<span class="preserve-lines">${esc(r.achievement1||'لم يُذكر')}</span>`],
      ['الإنجاز الثاني وأثره',`<span class="preserve-lines">${esc(r.achievement2||'لم يُذكر')}</span>`],
      ['الإنجاز الثالث وأثره',`<span class="preserve-lines">${esc(r.achievement3||'لم يُذكر')}</span>`],
      ['التحديات وكيفية التعامل معها',`<span class="preserve-lines">${esc(r.challenge||'لم يُذكر')}</span>`],
      ['ملاحظات إضافية',`<span class="preserve-lines">${esc(r.notes||'لم يُذكر')}</span>`]
    ]))}
    ${reportSection('سابعًا: الاحتياجات التدريبية والتقنية',needs.length?
      summaryTable(needs.map(n=>[esc(n.label),esc(n.level||'لم يُحدد'),esc(n.priority||'لم تُحدد')]),['الاحتياج','مستوى الإتقان أو التوفر','الأولوية']):'<p class="report-empty">لم تُسجل احتياجات تفصيلية.</p>')}
    ${reportSection('ثامنًا: تخصيص الاحتياج',summaryTable([
      ['احتياجات إضافية',`<span class="preserve-lines">${esc(r.otherTraining||'لم يُذكر')}</span>`],
      ['ارتباط الاحتياجات بالمهام',`<span class="preserve-lines">${esc(r.needsContext||'لم يُذكر')}</span>`],
      ['أسلوب التطوير المفضل',esc(r.preferredTraining||'لم يُذكر')]
    ]))}
    ${reportSection('تاسعًا: التطوير والنمو المهني',coursesRows.length?
      summaryTable(coursesRows,['النشاط','النوع','الجهة والتاريخ والساعات','المكتسب والتطبيق والأثر','الشاهد']):'<p class="report-empty">لم تُسجل أنشطة نمو مهني.</p>')}
    ${reportSection('عاشرًا: خطة التطوير القادمة',summaryTable([
      ['الجدارات المستهدفة',esc((r.developCompetencies||[]).join('، ')||'لم يُذكر')],
      ['الهدف التطويري القادم',`<span class="preserve-lines">${esc(r.growthGoal||'لم يُذكر')}</span>`],
      ['خطوات التنفيذ والأدوات',`<span class="preserve-lines">${esc(r.growthActions||'لم يُذكر')}</span>`],
      ['الموعد المستهدف',esc(r.growthDeadline||'لم يُحدد')],
      ['مقياس نجاح التطوير',esc(r.growthMeasure||'لم يُذكر')],
      ['الدعم المتوقع',`<span class="preserve-lines">${esc(r.support||'لم يُذكر')}</span>`],
      ['مقترحات تحسين بيئة العمل',`<span class="preserve-lines">${esc(r.suggestions||'لم يُذكر')}</span>`]
    ]))}
    ${reportSection('الحادي عشر: المرفقات والشواهد العامة',attachmentLinks.length?
      summaryTable(attachmentLinks.map((url,i)=>['المرفق '+num(i+1),reportLink(url,'فتح المرفق التفاعلي')])):'<p class="report-empty">لم تُرفق روابط عامة.</p>')}
    <div class="interactive-note"><b>روابط تفاعلية ورموز QR:</b> امسحي الباركود بالجوال أو اضغطي على زر «فتح الشاهد التفاعلي» داخل ملف PDF لعرض الشاهد أو المرفق مباشرة. يجب أن تكون صلاحية الملف «أي شخص لديه الرابط يمكنه العرض».</div>
    <div class="report-declaration">أقرّت الموظفة بصحة البيانات الواردة وتوفر الشواهد الداعمة لها ${isDraft?'ضمن نسخة المعاينة قبل الإرسال':'عند إرسال التقييم'} بتاريخ ${esc(reportDate)}. أُعد هذا التقرير لغرض التأمل المهني والمراجعة ودعم التطوير، ولا يتضمن درجات أو نقاطًا.</div>
    <div class="approval-grid"><div class="signature-box"><b>اسم الموظفة</b><span>${esc(r.name||'________________')}</span><p>التوقيع: ____________________</p><p>التاريخ: ____ / ____ / ______</p></div><div class="signature-box principal"><b>المديرة / شادية صالح دليم</b><span>التوقيع والاعتماد</span><p>التوقيع: ____________________</p><p>الختم: _____________________</p></div></div>
    <div class="report-footer">بصمتي المهنية · التأمل الذاتي في الجدارات والإنجازات المهنية · ${esc(schoolName)}</div>
  </article>`;
}

function showFormalReport(r,options={}){
  const back=options.back||'records';
  $('#content').innerHTML=title('ملف PDF التفاعلي','معاينة التقرير قبل التصدير','اضغطي «تصدير ومشاركة»، ثم اختاري حفظ كملف PDF أو شاركيه مباشرة. ستبقى روابط الشواهد قابلة للنقر داخل الملف.',`<div class="report-actions"><button class="btn" data-go="${back}">العودة</button> <button class="btn primary" id="print">▣ تصدير ومشاركة PDF</button></div>`)+`<div class="export-help"><b>على الآيفون:</b> من معاينة الطباعة اضغطي زر المشاركة، ثم اختاري «حفظ في الملفات» أو أرسليه عبر واتساب أو البريد كملف PDF.</div>`+formalReportHtml(r,!!options.isDraft);
  $('#print').onclick=()=>window.print();
  wire();
  window.scrollTo(0,0);
  if(options.autoPrint)setTimeout(()=>window.print(),180);
}

function printDraftReport(){
  const error=validateAll();
  if(error){step=error[0];render();toast(error[1]);return}
  if(!draft.declaration){toast('فعّلي الإقرار بصحة البيانات قبل تصدير التقرير.');return}
  showFormalReport({...JSON.parse(JSON.stringify(draft)),date:new Date().toISOString(),period:{...settings}},{back:'survey',isDraft:true,autoPrint:true});
}

function report(id){const r=records.find(item=>item.id===id);if(r)showFormalReport(r,{back:'records'});}

function wire(){
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render();window.scrollTo(0,0)});
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render()});
  document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>report(b.dataset.report));
  document.querySelectorAll('[data-growth-start]').forEach(b=>b.onclick=()=>{view='survey';step=4;render()});
  $('#print-draft')?.addEventListener('click',printDraftReport);
}

// Uploaded logo is rasterized before storage; SVG and remote image URLs are not accepted.
function safeLogoData(value){return typeof value==='string'&&value.length<=200000&&/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+=*$/.test(value)?value:''}
function reportLogoHtml(record={}){
  const logo=safeLogoData(settings.logoDataUrl)||safeLogoData(record.period?.logoDataUrl);
  return logo?`<div class="ministry-mark custom-ministry-mark"><img class="report-custom-logo" src="${esc(logo)}" alt="شعار التقرير"></div>`:'<div class="ministry-mark" aria-label="وزارة التعليم"><span class="mark-lines">≋</span><b>وزارة التعليم</b><small>Ministry of Education</small></div>';
}
function settingsView(){return title('تخصيص المساحة','إعدادات النموذج','خصّصي بيانات المدرسة والشعار المستخدم في تقاريرك.')+`<section class="card"><form id="settings-form"><div class="field"><label for="school-name">اسم المدرسة</label><input id="school-name" name="school" required maxlength="150" value="${esc(settings.school)}"></div><div class="formgrid"><div class="field"><label for="period-start">بداية فترة التقييم</label><input id="period-start" type="date" name="start" required value="${esc(settings.start)}"></div><div class="field"><label for="period-end">نهاية فترة التقييم</label><input id="period-end" type="date" name="end" required value="${esc(settings.end)}"></div></div><section class="logo-setting"><div><h2>شعار التقرير</h2><p>أضيفي صورة شعار الوزارة أو الشعار المطلوب ليظهر في الديباجة وملف PDF.</p><div class="field"><label for="report-logo-file">إضافة أو تغيير صورة الشعار</label><input id="report-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><small>صورة PNG أو JPG أو WebP بحجم لا يتجاوز ٥ ميجابايت. يُحفظ الشعار لهذا المتصفح ويُرفق بالتقييمات الجديدة.</small></div><button id="restore-report-logo" class="btn" type="button">إعادة الشعار الافتراضي</button><p id="logo-error" class="logo-error" role="alert"></p></div><div id="logo-preview" class="logo-preview" aria-label="معاينة الشعار">${reportLogoHtml()}</div></section><button id="save-settings" class="btn primary" type="submit">حفظ الإعدادات</button></form></section>`}
async function readLogoImage(file){
  if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('اختاري صورة بصيغة PNG أو JPG أو WebP.');
  if(file.size>5*1024*1024)throw new Error('حجم الصورة كبير؛ اختاري صورة أصغر من ٥ ميجابايت.');
  const source=URL.createObjectURL(file);
  try{
    const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('تعذّر فتح الصورة؛ اختاري صورة أخرى.'));img.src=source;});
    if(!image.naturalWidth||!image.naturalHeight||image.naturalWidth*image.naturalHeight>25000000)throw new Error('أبعاد الصورة كبيرة جدًا؛ اختاري نسخة أصغر.');
    const scale=Math.min(1,600/image.naturalWidth,400/image.naturalHeight);
    const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
    const ctx=canvas.getContext('2d');if(!ctx)throw new Error('تعذّرت معالجة الصورة على هذا الجهاز.');ctx.drawImage(image,0,0,canvas.width,canvas.height);
    let data=canvas.toDataURL('image/png');if(data.length>200000)data=canvas.toDataURL('image/webp',0.85);
    if(!safeLogoData(data))throw new Error('اختاري صورة شعار أبسط أو أصغر حجمًا.');return data;
  }finally{URL.revokeObjectURL(source);}
}
function mountLogoSettings(){
  const form=$('#settings-form');if(!form)return;
  let nextLogo=safeLogoData(settings.logoDataUrl),revision=0,busy=false;
  const error=$('#logo-error'),button=$('#save-settings'),input=$('#report-logo-file');
  const preview=()=>{$('#logo-preview').innerHTML=nextLogo?`<img class="report-custom-logo" src="${esc(nextLogo)}" alt="معاينة الشعار">`:'<span class="default-logo-caption">الشعار الافتراضي</span>';};
  input.addEventListener('change',async()=>{
    const file=input.files?.[0];if(!file)return;const current=++revision;busy=true;button.disabled=true;error.textContent='';
    try{const logo=await readLogoImage(file);if(current!==revision)return;nextLogo=logo;preview();}
    catch(e){if(current===revision){error.textContent=e.message;input.value='';}}
    finally{if(current===revision){busy=false;button.disabled=false;}}
  });
  $('#restore-report-logo').onclick=()=>{revision++;busy=false;button.disabled=false;nextLogo='';input.value='';error.textContent='';preview();};
  form.addEventListener('submit',e=>{
    e.preventDefault();if(busy)return;
    const s={school:form.elements.school.value.trim(),start:form.elements.start.value,end:form.elements.end.value,logoDataUrl:nextLogo};
    if(s.start>s.end){error.textContent='تاريخ النهاية يجب ألا يسبق البداية.';return;}
    if(!s.school){error.textContent='أدخلي اسم المدرسة.';return;}
    if(save('settings',s)){settings=s;render();}
  });
}

document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;if(b.dataset.participation!==undefined)step=3;render();window.scrollTo(0,0)});render();
